-- Foto do Lápis Contorno Labial Nude (ULE-011-RMLP02BB), enviada pelo Daniel
INSERT INTO "stored_files" ("id", "area", "fileName", "mimeType", "sizeBytes", "data", "createdAt")
SELECT gen_random_uuid(), 'products', 'ruby-kisses-lapis-labial-nude.webp', 'image/webp', 18040, decode('', 'hex'), now()
WHERE NOT EXISTS (SELECT 1 FROM "stored_files" WHERE "fileName" = 'ruby-kisses-lapis-labial-nude.webp');
INSERT INTO "product_images" ("id", "productId", "fileName", "mimeType", "isPrimary", "sortOrder", "createdAt")
SELECT gen_random_uuid(), p."id", 'ruby-kisses-lapis-labial-nude.webp', 'image/webp', true, 0, now()
  FROM "products" p
 WHERE p."sku" = 'ULE-011-RMLP02BB' AND NOT EXISTS (SELECT 1 FROM "product_images" i WHERE i."productId" = p."id");
UPDATE "products" SET "internalNotes" = 'PREÇO DE TESTE (R$ 1,00). Definir o preço real após a reunião com o contador.', "updatedAt" = now()
 WHERE "sku" = 'ULE-011-RMLP02BB';
